package com.voicepacks;

import com.voicepacks.trigger.EventType;
import com.voicepacks.trigger.GameEvent;

/**
 * {@code ::vp <event> [field=value ...]}: fakes an event so any line can be heard without grinding for it, e.g.
 * {@code ::vp boss_kc boss=Zulrah kc=1 first=true} or {@code ::vp pet pet=Baby_mole}. Underscores become spaces;
 * true/false and numbers are typed. Simulated events don't touch journey memory.
 */
final class DemoCommand
{
	static final String USAGE = "::vp demo [N]  |  ::vp <event> [field=value ...], e.g. ::vp pet pet=Snakeling  |  ::vp list";

	/** What {@code ::vp demo} steps through, one per use; matches the example pack's showcase triggers. */
	static final String[] SHOWCASE = {
		"level_up skill=attack level=40",
		"level_up skill=woodcutting level=40",
		"level_up level=99 milestone=99",
		"quest_complete quest=Cook's_Assistant",
		"quest_complete quest=Dragon_Slayer_I",
		"boss_kc boss=Zulrah kc=1 first=true",
		"boss_kc boss=Zulrah kc=500",
		"collection_log item=Tanzanite_fang dryKc=412",
		"pet pet=Snakeling",
		"loot source=Zulrah item=Tanzanite_fang value=5000000 record=true",
		"clue_complete tier=master first=true",
		"login daysAway=10",
		"login timeOfDay=late",
		"boss_kc boss=Vorkath afterAction=true",
		"death",
		// specific lines: an example pack's per-quest, per-boss, per-pet and per-item triggers
		"quest_complete quest=Song_of_the_Elves",
		"boss_kc boss=TzTok-Jad kc=1",
		"boss_kc boss=Vorkath kc=250",
		"pet pet=Vorki",
		"collection_log item=Twisted_bow",
		"collection_log item=Scythe_of_Vitur",
	};

	private DemoCommand()
	{
	}

	/**
	 * The arguments for showcase step {@code n} (1-based, wraps around).
	 */
	static String[] showcase(int n)
	{
		int i = Math.floorMod(n - 1, SHOWCASE.length);
		return SHOWCASE[i].split(" ");
	}

	/** @return the event type named by {@code args[0]}, or null */
	static EventType type(String[] args)
	{
		return args.length == 0 ? null : EventType.fromKey(args[0]);
	}

	/** Sets each {@code field=value} argument on the event, overriding anything already there. */
	static GameEvent apply(GameEvent e, String[] args)
	{
		for (int i = 1; i < args.length; i++)
		{
			int eq = args[i].indexOf('=');
			if (eq > 0)
			{
				e.with(args[i].substring(0, eq), value(args[i].substring(eq + 1)));
			}
		}
		return e;
	}

	private static Object value(String raw)
	{
		if ("true".equalsIgnoreCase(raw) || "false".equalsIgnoreCase(raw))
		{
			return Boolean.parseBoolean(raw);
		}
		if (raw.matches("-?\\d+"))
		{
			return Long.parseLong(raw);
		}
		return raw.replace('_', ' ');
	}
}

package com.voicepacks;

import java.util.Set;

/**
 * Boss rooms and raids where lines are held until the player leaves, so a line never talks over a fight (the "Hold
 * lines during boss fights" setting, on by default). The triggers are fixed achievement events, not mechanic cues,
 * so the hub reviewer (2026-10-25) said no restriction is required; this is a courtesy. Copied from the Watchdog
 * plugin's Region.java as of its hub commit 3360e0a (2026-10-21; plugin-hub plugins/watchdog); keep it in sync with
 * that list. Hydra and Kalphite Queen count everywhere here, though Watchdog limits them to the instance and plane 0.
 */
final class RestrictedRegions
{
	private static final Set<Integer> REGIONS = Set.of(
		5536,                                      // Alchemical Hydra (instance)
		4405, 8291, 10595, 12132,                  // Vardorvis, Leviathan, Whisperer, Sucellus
		9023, 9043, 9551, 7216,                    // Vorkath, Inferno, Fight Caves, Colosseum
		13972,                                     // Kalphite Queen
		13136, 13137, 13393, 13138, 13394, 13139, 13395, 13140, 13396, 13141, 13397, 13145, 13401, 12889, // CoX
		12613, 13125, 13122, 13123, 13379, 12612, 12611, // ToB
		14160, 15698, 15700, 14162, 14164, 15186, 15188, 14674, 14676, 15184, 15696, // ToA
		6045, 5269, 13668, 14180, 15515,           // Yama, Doom of Mokhaiotl, Nightmare
		11330, 11645, 11901,                       // Phantom Muspah, Maggot King
		16214, 16726, 16215, 16727, 16216, 16728, 16472, 16471 // TFA
	);

	private RestrictedRegions()
	{
	}

	static boolean contains(int regionId)
	{
		return REGIONS.contains(regionId);
	}
}

package com.voicepacks;

import com.voicepacks.audio.VoicePlayer;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(VoicePacksConfig.GROUP)
public interface VoicePacksConfig extends Config
{
	String GROUP = "voicepacks";

	@Range(max = 100)
	@ConfigItem(keyName = "volume", name = "Volume", description = "Master volume for voice lines", position = 1)
	default int volume()
	{
		return 80;
	}

	@ConfigItem(keyName = "enabledPacks", name = "Enabled packs",
		description = "Comma-separated pack ids to load (folder names under .runelite/plugin-data/voice-packs/packs). Empty loads all.",
		position = 2)
	default String enabledPacks()
	{
		return "";
	}

	@ConfigItem(keyName = "overlap", name = "When a line is playing",
		description = "Queue the new line until the current one ends, drop it, or play both at once", position = 3)
	default VoicePlayer.Overlap overlap()
	{
		return VoicePlayer.Overlap.QUEUE;
	}

	@Range(max = 60)
	@ConfigItem(keyName = "minGapSeconds", name = "Minimum gap (s)",
		description = "Never start lines closer together than this", position = 4)
	default int minGapSeconds()
	{
		return 2;
	}

	@ConfigItem(keyName = "subtitles", name = "Subtitles", description = "Also print each line in the chat box",
		position = 5)
	default boolean subtitles()
	{
		return true;
	}

	@ConfigItem(keyName = "holdInBossAreas", name = "Hold lines during boss fights",
		description = "In boss rooms and raids, save lines until you leave instead of playing them mid-fight",
		position = 6)
	default boolean holdInBossAreas()
	{
		return true;
	}
}

package com.voicepacks;

import com.voicepacks.pack.PackManifest;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/** Sidebar panel: the installed packs, an Import button for pack zips, and Remove per pack. Swing thread only. */
class VoicePacksPanel extends PluginPanel
{
	private final JPanel list = new JPanel();
	private final JLabel status = new JLabel();
	private final Consumer<String> onRemove;

	VoicePacksPanel(Runnable onImport, Consumer<String> onRemove)
	{
		this.onRemove = onRemove;
		setLayout(new BorderLayout(0, 8));
		setBorder(new EmptyBorder(10, 10, 10, 10));

		JPanel top = new JPanel(new GridLayout(0, 1, 0, 6));
		JLabel title = new JLabel("Voice Packs");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		top.add(title);
		JButton importButton = new JButton("Import pack (.zip)…");
		importButton.setToolTipText("Install a voice pack zip someone sent you");
		importButton.addActionListener(e -> onImport.run());
		top.add(importButton);
		status.setFont(FontManager.getRunescapeSmallFont());
		status.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		top.add(status);
		add(top, BorderLayout.NORTH);

		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		add(list, BorderLayout.CENTER);
		setPacks(List.of());
	}

	void setStatus(String text)
	{
		status.setText("<html>" + escape(text) + "</html>");
	}

	void setPacks(List<PackManifest> packs)
	{
		list.removeAll();
		if (packs.isEmpty())
		{
			JLabel none = new JLabel("<html>No packs installed. Import a pack zip to start.</html>");
			none.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			list.add(none);
		}
		for (PackManifest m : packs)
		{
			list.add(row(m));
			list.add(javax.swing.Box.createVerticalStrut(6));
		}
		list.revalidate();
		list.repaint();
	}

	private JPanel row(PackManifest m)
	{
		JPanel row = new JPanel(new BorderLayout(6, 2));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		row.setMaximumSize(new Dimension(PANEL_WIDTH, 80));

		int lines = m.triggers.stream().mapToInt(t -> t.lines.size()).sum();
		boolean personal = m.voice != null && "private".equals(m.voice.distribution);
		JLabel name = new JLabel("<html><b>" + escape(m.name) + "</b> " + escape(m.version) + "<br>"
			+ lines + " lines" + (personal ? " · private, don't share" : "") + "</html>");
		name.setForeground(Color.WHITE);
		name.setToolTipText(m.description);
		row.add(name, BorderLayout.CENTER);

		JButton remove = new JButton("Remove");
		remove.addActionListener(e ->
		{
			int ok = JOptionPane.showConfirmDialog(this, "Remove the " + m.name + " voice pack?", "Voice Packs",
				JOptionPane.OK_CANCEL_OPTION);
			if (ok == JOptionPane.OK_OPTION)
			{
				onRemove.accept(m.id);
			}
		});
		row.add(remove, BorderLayout.EAST);
		return row;
	}

	private static String escape(String s)
	{
		return s == null ? "" : s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.voicepacks;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.inject.Provides;
import com.voicepacks.audio.VoicePlayer;
import com.voicepacks.journey.ContextProvider;
import com.voicepacks.journey.JourneyStore;
import com.voicepacks.pack.PackImporter;
import com.voicepacks.pack.PackLoader;
import com.voicepacks.pack.PackManifest;
import com.voicepacks.source.ChatSource;
import com.voicepacks.source.LootSource;
import com.voicepacks.source.ProgressSource;
import com.voicepacks.trigger.EventSink;
import com.voicepacks.trigger.EventType;
import com.voicepacks.trigger.GameEvent;
import com.voicepacks.trigger.TriggerEngine;
import java.io.IOException;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.stream.Collectors;
import javax.swing.SwingUtilities;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.ImageUtil;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
	name = "Voice Packs",
	internalName = "voice-packs",
	description = "Plays pre-generated voice lines from installable voice packs",
	tags = {"voice", "sound", "tts", "announce", "level", "quest"}
)
public class VoicePacksPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(VoicePacksPlugin.class);
	private static final String JOURNEY_KEY = "journey";
	/** Lines saved up in a boss or raid region play after leaving it, unless they're older than this. */
	private static final long AFTER_ACTION_MAX_AGE_MS = 10 * 60_000;
	private static final int AFTER_ACTION_MAX = 30;
	private static final int SAVE_EVERY_TICKS = 100;   // about a minute

	@Inject
	private Client client;

	@Inject
	private EventBus eventBus;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private VoicePacksConfig config;

	@Inject
	private EventSink sink;

	@Inject
	private ChatSource chatSource;

	@Inject
	private ProgressSource progressSource;

	@Inject
	private LootSource lootSource;

	@Inject
	private ContextProvider context;

	@Inject
	private PackLoader packLoader;

	@Inject
	private VoicePlayer player;

	@Inject
	private PackImporter importer;

	@Inject
	private ClientToolbar clientToolbar;

	private final JourneyStore journey = new JourneyStore();
	private final List<Deferred> afterAction = new ArrayList<>();
	private volatile PackLoader.Loaded loaded;
	private boolean journeyLoaded;
	private long lastPlayMs;
	private int ticksSinceSave;
	private int demoStep;
	private VoicePacksPanel panel;
	private NavigationButton navButton;

	/** An event that happened in a boss area while lines are held, waiting for the player to leave it. */
	private static final class Deferred
	{
		final GameEvent event;
		final long atMs;

		Deferred(GameEvent event, long atMs)
		{
			this.event = event;
			this.atMs = atMs;
		}
	}

	@Override
	protected void startUp()
	{
		eventBus.register(chatSource);
		eventBus.register(progressSource);
		eventBus.register(lootSource);
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			loadJourney();
		}
		panel = new VoicePacksPanel(this::importPack, this::removePack);
		navButton = NavigationButton.builder()
			.tooltip("Voice Packs")
			.icon(ImageUtil.loadImageResource(getClass(), "icon.png"))
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		executor.execute(this::reloadPacks);
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
		saveJourney();
		eventBus.unregister(chatSource);
		eventBus.unregister(progressSource);
		eventBus.unregister(lootSource);
		progressSource.reset();
		sink.drain();
		afterAction.clear();
		player.stop();
		loaded = null;
		journeyLoaded = false;
	}

	@Provides
	VoicePacksConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(VoicePacksConfig.class);
	}

	// ------------------------------------------------------------------ packs

	private void reloadPacks()
	{
		Set<String> enabled = Arrays.stream(config.enabledPacks().split(","))
			.map(String::trim).filter(s -> !s.isEmpty()).collect(Collectors.toSet());
		try
		{
			PackLoader.Loaded result = packLoader.load(packsDir(), enabled);
			result.engine.setPlayCounts(new TriggerEngine.PlayCounts()
			{
				@Override
				public int plays(String lineKey)
				{
					return journey.linePlays(lineKey);
				}

				@Override
				public void played(String lineKey)
				{
					journey.linePlayed(lineKey);
				}
			});
			loaded = result;
			showPacks(result.manifests);
		}
		catch (Exception e)
		{
			log.warn("Could not load voice packs", e);
		}
	}

	private Filepath packsDir() throws IOException
	{
		return getPluginDirectory().joinSegment("packs");
	}

	private void showPacks(List<PackManifest> manifests)
	{
		List<PackManifest> copy = new ArrayList<>(manifests);
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.setPacks(copy);
			}
		});
	}

	private void showStatus(String text)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (panel != null)
			{
				panel.setStatus(text);
			}
		});
	}

	/** Swing thread: pick a zip, then unpack and reload off it. */
	private void importPack()
	{
		List<Filepath> picked = new Filepath.Chooser()
			.setIsOpen()
			.setAcceptsFiles()
			.setDialogTitle("Import a voice pack")
			.addExtensionFilter("Voice pack (.zip)", "zip")
			.showDialog(panel);
		if (picked == null || picked.isEmpty())
		{
			return;
		}
		Filepath zip = picked.get(0);
		panel.setStatus("Importing " + zip.getFileName() + "…");
		executor.execute(() ->
		{
			try
			{
				PackManifest m = importer.importZip(zip, packsDir());
				reloadPacks();
				showStatus("Installed " + m.name + " " + m.version + ".");
			}
			catch (Exception e)
			{
				log.warn("Could not import voice pack {}", zip, e);
				showStatus("Couldn't import that zip: " + e.getMessage());
			}
		});
	}

	private void removePack(String id)
	{
		executor.execute(() ->
		{
			try
			{
				Filepath dir = packsDir().joinSegment(id);
				if (dir.exists())
				{
					dir.deleteRecursively();
				}
				reloadPacks();
				showStatus("Removed " + id + ".");
			}
			catch (Exception e)
			{
				log.warn("Could not remove voice pack {}", id, e);
				showStatus("Couldn't remove " + id + ": " + e.getMessage());
			}
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (VoicePacksConfig.GROUP.equals(event.getGroup())
			&& "enabledPacks".equals(event.getKey()))
		{
			executor.execute(this::reloadPacks);
		}
	}

	// ------------------------------------------------------------------ journey memory

	private void loadJourney()
	{
		String json = configManager.getRSProfileConfiguration(VoicePacksConfig.GROUP, JOURNEY_KEY);
		try
		{
			journey.setData(json == null ? null : gson.fromJson(json, JourneyStore.Data.class));
		}
		catch (JsonParseException e)
		{
			log.warn("Unreadable voice pack journey data; starting fresh", e);
			journey.setData(null);
		}
		journeyLoaded = true;
	}

	private void saveJourney()
	{
		if (journeyLoaded && journey.takeDirty())
		{
			configManager.setRSProfileConfiguration(VoicePacksConfig.GROUP, JOURNEY_KEY, gson.toJson(journey.getData()));
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		loadJourney();                              // the previous account was saved at logout
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			saveJourney();
			afterAction.clear();
		}
	}

	// ------------------------------------------------------------------ playing lines

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		long now = System.currentTimeMillis();
		boolean restricted = config.holdInBossAreas() && inRestrictedRegion();
		List<GameEvent> events = sink.drain();
		// Kill counts first, so a pet or collection-log item in the same tick is credited to that kill.
		events.sort(Comparator.comparing(e -> e.getType() != EventType.BOSS_KC));
		for (GameEvent e : events)
		{
			annotate(e, now);
		}
		if (journeyLoaded)
		{
			journey.seen(now);                       // after annotating, so LOGIN still sees the old lastSeen
			if (++ticksSinceSave >= SAVE_EVERY_TICKS)
			{
				ticksSinceSave = 0;
				saveJourney();
			}
		}

		if (restricted)
		{
			for (GameEvent e : events)
			{
				if (afterAction.size() < AFTER_ACTION_MAX)
				{
					afterAction.add(new Deferred(e.with("afterAction", true), now));
				}
			}
			return;
		}
		if (!afterAction.isEmpty())
		{
			if (now - lastPlayMs < config.minGapSeconds() * 1000L)
			{
				return;                              // keep them until the gap has passed
			}
			afterAction.removeIf(d -> now - d.atMs > AFTER_ACTION_MAX_AGE_MS);
			afterAction.forEach(d -> events.add(d.event));
			afterAction.clear();
		}
		play(events, now);
	}

	private void annotate(GameEvent e, long now)
	{
		if (e.getType() == EventType.LOGIN)
		{
			context.loggedIn(now);
		}
		context.fill(e, now, LocalDateTime.now());
		if (journeyLoaded)
		{
			journey.annotate(e, now);
		}
	}

	/** @return the line that played, or null */
	private TriggerEngine.Selection play(List<GameEvent> events, long now)
	{
		PackLoader.Loaded packs = loaded;
		if (events.isEmpty() || packs == null || now - lastPlayMs < config.minGapSeconds() * 1000L)
		{
			return null;
		}
		TriggerEngine.Selection best = null;
		for (GameEvent event : events)
		{
			TriggerEngine.Selection s = packs.engine.select(event, now);
			if (s != null && (best == null || s.priority > best.priority))
			{
				best = s;
			}
		}
		if (best == null)
		{
			return null;
		}
		double linear = config.volume() / 100.0 * best.volume;
		if (linear <= 0)
		{
			return null;
		}
		lastPlayMs = now;
		float gainDb = (float) (20 * Math.log10(linear) + best.line.gainDb);
		player.play(packs.audioFor(best.packId, best.line.file), gainDb, best.priority, config.overlap());
		if (config.subtitles() && best.line.text != null)
		{
			say(best.line.text);
		}
		return best;
	}

	private void say(String text)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(text)
			.build());
	}

	// ------------------------------------------------------------------ demo

	@Subscribe
	public void onCommandExecuted(CommandExecuted command)
	{
		if (!"vp".equalsIgnoreCase(command.getCommand()))
		{
			return;
		}
		String[] args = command.getArguments();
		PackLoader.Loaded packs = loaded;
		if (args.length > 0 && "list".equalsIgnoreCase(args[0]))
		{
			say(packs == null ? "Voice packs: none loaded"
				: "Voice packs: " + packs.packs + ", " + packs.engine.size() + " triggers");
			return;
		}
		if (args.length > 0 && "demo".equalsIgnoreCase(args[0]))
		{
			int step = args.length > 1 && args[1].matches("\\d+") ? Integer.parseInt(args[1]) : demoStep + 1;
			demoStep = Math.floorMod(step - 1, DemoCommand.SHOWCASE.length) + 1;
			args = DemoCommand.showcase(demoStep);
			say("Demo " + demoStep + "/" + DemoCommand.SHOWCASE.length + ": " + String.join(" ", args));
		}
		EventType type = DemoCommand.type(args);
		if (type == null)
		{
			say(DemoCommand.USAGE);
			return;
		}
		long now = System.currentTimeMillis();
		GameEvent event = new GameEvent(type);
		context.fill(event, now, LocalDateTime.now());   // real context, no journey memory...
		DemoCommand.apply(event, args);                  // ...and typed fields override both
		lastPlayMs = 0;                                   // a demo shouldn't wait out the gap
		if (play(List.of(event), now) == null)
		{
			say("Voice packs: no line matches " + event + " (or it's cooling down)");
		}
	}

	private boolean inRestrictedRegion()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return false;
		}
		WorldPoint wp = WorldPoint.fromLocalInstance(client, local.getLocalLocation());
		return wp != null && RestrictedRegions.contains(wp.getRegionID());
	}
}

package com.voicepacks.audio;

import java.io.BufferedInputStream;
import java.io.DataInputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.util.Filepath;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * One voice channel on top of RuneLite's {@link AudioPlayer} (the Plugin Hub doesn't allow javax.sound directly).
 * AudioPlayer can't stop a clip or say when it ends, so the channel reads each clip's length from its WAV header and
 * keeps track of when the voice is free: a line that arrives while another is playing waits for it (QUEUE), is
 * skipped (DROP) or plays over it (OVERLAP). At most one line waits; a more important one replaces it.
 */
@Singleton
public class VoicePlayer
{
	private static final Logger log = LoggerFactory.getLogger(VoicePlayer.class);

	public enum Overlap
	{
		QUEUE, DROP, OVERLAP
	}

	private static final class Line
	{
		final Filepath file;
		final float gainDb;
		final int priority;

		Line(Filepath file, float gainDb, int priority)
		{
			this.file = file;
			this.gainDb = gainDb;
			this.priority = priority;
		}
	}

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private AudioPlayer audioPlayer;

	private long busyUntilMs;
	private Line waiting;

	/** @param gainDb total gain (master volume, pack volume and per-line trim combined) */
	public void play(Filepath file, float gainDb, int priority, Overlap overlap)
	{
		executor.execute(() -> request(new Line(file, gainDb, priority), overlap));
	}

	/** Forgets the waiting line. A line already playing finishes (clips are a few seconds long). */
	public synchronized void stop()
	{
		waiting = null;
	}

	private synchronized void request(Line line, Overlap overlap)
	{
		long now = System.currentTimeMillis();
		if (now >= busyUntilMs || overlap == Overlap.OVERLAP)
		{
			start(line, now);
		}
		else if (overlap == Overlap.QUEUE && (waiting == null || line.priority >= waiting.priority))
		{
			waiting = line;
			executor.schedule(this::playWaiting, busyUntilMs - now, TimeUnit.MILLISECONDS);
		}
	}

	private synchronized void playWaiting()
	{
		long now = System.currentTimeMillis();
		if (waiting == null || now < busyUntilMs)
		{
			return;     // already played, or a later line moved the end; that line's own schedule plays it
		}
		Line line = waiting;
		waiting = null;
		start(line, now);
	}

	private void start(Line line, long now)
	{
		long lengthMs;
		try (InputStream in = line.file.openInputStream())
		{
			lengthMs = wavLengthMs(in);
		}
		catch (IOException e)
		{
			lengthMs = 0;
			log.debug("No length for {}: {}", line.file, e.getMessage());
		}
		try
		{
			audioPlayer.play(line.file, line.gainDb);
		}
		catch (Exception e)
		{
			log.warn("Could not play {}: {}", line.file, e.getMessage());
			return;
		}
		busyUntilMs = Math.max(busyUntilMs, now + lengthMs);
	}

	/** The length of a RIFF/WAVE file from its header: the data chunk's size over the fmt chunk's byte rate. */
	static long wavLengthMs(InputStream raw) throws IOException
	{
		DataInputStream in = new DataInputStream(new BufferedInputStream(raw));
		if (!"RIFF".equals(fourCc(in)))
		{
			throw new IOException("not a RIFF file");
		}
		in.readInt();
		if (!"WAVE".equals(fourCc(in)))
		{
			throw new IOException("not a WAVE file");
		}
		long byteRate = 0;
		while (true)
		{
			String chunk = fourCc(in);
			long size = Integer.reverseBytes(in.readInt()) & 0xffffffffL;
			if (chunk.equals("fmt ") && size >= 16)
			{
				skip(in, 8);                // format, channels, sample rate
				byteRate = Integer.reverseBytes(in.readInt()) & 0xffffffffL;
				skip(in, size - 12 + (size & 1));
			}
			else if (chunk.equals("data"))
			{
				if (byteRate == 0)
				{
					throw new IOException("data before fmt");
				}
				return size * 1000 / byteRate;
			}
			else
			{
				skip(in, size + (size & 1));
			}
		}
	}

	private static String fourCc(DataInputStream in) throws IOException
	{
		byte[] b = new byte[4];
		in.readFully(b);
		return new String(b, StandardCharsets.US_ASCII);
	}

	private static void skip(InputStream in, long n) throws IOException
	{
		while (n > 0)
		{
			long s = in.skip(n);
			if (s <= 0)
			{
				if (in.read() < 0)
				{
					throw new EOFException();
				}
				s = 1;
			}
			n -= s;
		}
	}
}

package com.voicepacks.journey;

import com.voicepacks.trigger.GameEvent;
import java.time.LocalDateTime;
import java.time.MonthDay;
import java.util.EnumSet;
import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldType;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.vars.AccountType;

/** Fills the context fields (who the player is, when and where) that every trigger can filter on. */
@Singleton
public class ContextProvider
{
	@Inject
	private Client client;

	private long loginAtMs;

	public void loggedIn(long nowMs)
	{
		loginAtMs = nowMs;
	}

	/** Call on the client thread. */
	public void fill(GameEvent e, long nowMs, LocalDateTime now)
	{
		Player local = client.getLocalPlayer();
		e.with("account", account(client.getAccountType()))
			.with("totalLevel", client.getTotalLevel())
			.with("questPoints", client.getVarpValue(VarPlayerID.QP))
			.with("world", world(client.getWorldType()))
			.with("inWilderness", client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 1)
			.with("sessionMinutes", loginAtMs == 0 ? 0 : (int) ((nowMs - loginAtMs) / 60_000))
			.with("afterAction", false);
		if (local != null)
		{
			e.with("combatLevel", local.getCombatLevel());
		}
		addTime(e, now);
	}

	static void addTime(GameEvent e, LocalDateTime now)
	{
		e.with("timeOfDay", timeOfDay(now.getHour()))
			.with("weekday", now.getDayOfWeek().name().toLowerCase(Locale.ROOT))
			.with("holiday", holiday(MonthDay.from(now)));
	}

	static String timeOfDay(int hour)
	{
		if (hour >= 5 && hour < 12)
		{
			return "morning";
		}
		if (hour >= 12 && hour < 17)
		{
			return "afternoon";
		}
		if (hour >= 17 && hour < 23)
		{
			return "evening";
		}
		return "late";
	}

	static String holiday(MonthDay d)
	{
		switch (d.getMonthValue() * 100 + d.getDayOfMonth())
		{
			case 1231:
			case 101:
				return "new_year";
			case 214:
				return "valentines";
			case 1031:
				return "halloween";
			case 1224:
			case 1225:
			case 1226:
				return "christmas";
			default:
				return "none";
		}
	}

	private static String account(AccountType t)
	{
		if (t == null)
		{
			return "main";
		}
		switch (t)
		{
			case IRONMAN:
				return "ironman";
			case ULTIMATE_IRONMAN:
				return "ultimate";
			case HARDCORE_IRONMAN:
				return "hardcore";
			case GROUP_IRONMAN:
				return "group";
			case HARDCORE_GROUP_IRONMAN:
				return "hardcore_group";
			default:
				return "main";
		}
	}

	private static String world(EnumSet<WorldType> types)
	{
		if (types.contains(WorldType.SEASONAL))
		{
			return "leagues";
		}
		if (types.contains(WorldType.DEADMAN))
		{
			return "deadman";
		}
		return types.contains(WorldType.MEMBERS) ? "members" : "f2p";
	}
}

package com.voicepacks.journey;

import com.voicepacks.trigger.EventType;
import com.voicepacks.trigger.GameEvent;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * What the narrator remembers about one account: how often things happened and when, kills since the last unique
 * per boss, best drops, the last time the player was seen, and how often each line has played. Pure Java (no
 * RuneLite types); the plugin persists {@link Data} as JSON in the account's RuneLite profile.
 *
 * <p>{@link #annotate} is called once per event, when it happens (even if no line ends up playing), and adds the
 * journey fields packs can filter on: first, count, firstAll, countAll, sinceLastDays, plus dryKc / boss on
 * BOSS_KC, COLLECTION_LOG and PET, record / sourceRecord on LOOT, and daysAway on LOGIN.
 */
public class JourneyStore
{
	private static final long DAY_MS = 24L * 60 * 60 * 1000;
	/** A collection-log item or pet this soon after a kill count message is credited to that boss. */
	private static final long ATTRIBUTION_MS = 15_000;

	/** The persisted state. Field names are the JSON keys. */
	public static class Data
	{
		public Map<String, Integer> counts = new HashMap<>();
		public Map<String, Long> lastAt = new HashMap<>();
		public Map<String, Integer> dryKc = new HashMap<>();
		public Map<String, Long> bestLoot = new HashMap<>();
		public Map<String, Integer> linePlays = new HashMap<>();
		public long lastSeen;
	}

	private Data data = new Data();
	private String lastBoss;
	private long lastBossAt;
	private boolean dirty;

	public Data getData()
	{
		return data;
	}

	public void setData(Data data)
	{
		this.data = data == null ? new Data() : fill(data);
		lastBoss = null;
		dirty = false;
	}

	/** True once since the last call if anything changed (the plugin uses this to decide when to save). */
	public boolean takeDirty()
	{
		boolean d = dirty;
		dirty = false;
		return d;
	}

	public void annotate(GameEvent e, long nowMs)
	{
		EventType type = e.getType();
		switch (type)
		{
			case BOSS_KC:
				bossKill(e, nowMs);
				break;
			case COLLECTION_LOG:
			case PET:
				creditUnique(e, nowMs);
				break;
			case LOOT:
				loot(e);
				break;
			case LOGIN:
				if (data.lastSeen > 0)
				{
					e.with("daysAway", (int) ((nowMs - data.lastSeen) / DAY_MS));
				}
				break;
			default:
				break;
		}

		String all = type.name();
		String keyed = type.getKeyField() == null ? all : all + ":" + norm(e.get(type.getKeyField()));
		Long before = data.lastAt.get(keyed);
		int countAll = bump(all, nowMs);
		int count = keyed.equals(all) ? countAll : bump(keyed, nowMs);
		e.with("countAll", countAll).with("firstAll", countAll == 1)
			.with("count", count).with("first", count == 1);
		if (before != null)
		{
			e.with("sinceLastDays", (int) ((nowMs - before) / DAY_MS));
		}
		dirty = true;
	}

	/** Called every game tick while logged in, so daysAway works however the session ends. */
	public void seen(long nowMs)
	{
		data.lastSeen = nowMs;
	}

	public int linePlays(String lineKey)
	{
		return data.linePlays.getOrDefault(lineKey, 0);
	}

	public void linePlayed(String lineKey)
	{
		data.linePlays.merge(lineKey, 1, Integer::sum);
		dirty = true;
	}

	// ------------------------------------------------------------------ internals

	private int bump(String key, long nowMs)
	{
		data.lastAt.put(key, nowMs);
		return data.counts.merge(key, 1, Integer::sum);
	}

	private void bossKill(GameEvent e, long nowMs)
	{
		String boss = norm(e.get("boss"));
		int dry = data.dryKc.merge(boss, 1, Integer::sum);
		e.with("dryKc", dry);
		lastBoss = boss;
		lastBossAt = nowMs;
	}

	private void creditUnique(GameEvent e, long nowMs)
	{
		if (lastBoss == null || nowMs - lastBossAt > ATTRIBUTION_MS)
		{
			return;
		}
		Integer dry = data.dryKc.put(lastBoss, 0);
		e.with("boss", lastBoss).with("dryKc", dry == null ? 0 : dry);
	}

	private void loot(GameEvent e)
	{
		Object v = e.get("value");
		if (!(v instanceof Number))
		{
			return;
		}
		long value = ((Number) v).longValue();
		long bestAll = data.bestLoot.getOrDefault("*", 0L);
		String sourceKey = norm(e.get("source"));
		long bestSource = data.bestLoot.getOrDefault(sourceKey, 0L);
		e.with("record", bestAll > 0 && value > bestAll).with("sourceRecord", bestSource > 0 && value > bestSource);
		if (value > bestAll)
		{
			data.bestLoot.put("*", value);
		}
		if (value > bestSource)
		{
			data.bestLoot.put(sourceKey, value);
		}
	}

	private static String norm(Object o)
	{
		return o == null ? "" : String.valueOf(o).toLowerCase(Locale.ROOT);
	}

	/** Gson leaves maps null when a saved blob predates a field. */
	private static Data fill(Data d)
	{
		Data blank = new Data();
		d.counts = d.counts == null ? blank.counts : d.counts;
		d.lastAt = d.lastAt == null ? blank.lastAt : d.lastAt;
		d.dryKc = d.dryKc == null ? blank.dryKc : d.dryKc;
		d.bestLoot = d.bestLoot == null ? blank.bestLoot : d.bestLoot;
		d.linePlays = d.linePlays == null ? blank.linePlays : d.linePlays;
		return d;
	}
}

package com.voicepacks.pack;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.Reader;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.util.Filepath;

/**
 * Installs a pack zip (as made by `vpack zip`: one top folder named after the pack id, holding voicepack.json and
 * audio/*.wav) into the packs folder. Anything else in the zip is ignored; sizes are counted while unpacking, not
 * taken from the zip's headers. The pack is unpacked into a hidden folder first and only replaces an installed
 * pack of the same id once its manifest reads.
 */
@Singleton
public class PackImporter
{
	private static final Pattern ENTRY = Pattern.compile("([a-z0-9][a-z0-9-]{0,63})/(voicepack\\.json|audio/[A-Za-z0-9._-]+\\.wav)");
	private static final long MAX_MANIFEST_BYTES = 4L << 20;
	private static final long MAX_PACK_BYTES = 600L << 20;
	private static final int MAX_FILES = 5000;

	@Inject
	private Gson gson;

	public PackImporter()
	{
	}

	PackImporter(Gson gson)
	{
		this.gson = gson;
	}

	/** @return the installed pack's manifest */
	public PackManifest importZip(Filepath zip, Filepath packsDir) throws IOException
	{
		if (!packsDir.exists())
		{
			packsDir.createDirectories();
		}
		Filepath staging = packsDir.createTempDir(".import-");
		try
		{
			String id = unpack(zip, staging);
			Filepath unpacked = staging.joinSegment(id);
			PackManifest m = readManifest(unpacked);
			if (!id.equals(m.id))
			{
				throw new IOException("the zip's folder is " + id + " but the pack's id is " + m.id);
			}
			Filepath dest = packsDir.joinSegment(id);
			if (dest.exists())
			{
				dest.deleteRecursively();
			}
			unpacked.moveTo(dest);
			return m;
		}
		finally
		{
			staging.deleteRecursively();
		}
	}

	private String unpack(Filepath zip, Filepath staging) throws IOException
	{
		String id = null;
		long total = 0;
		int files = 0;
		try (InputStream in = zip.openInputStream(); ZipInputStream z = new ZipInputStream(in))
		{
			for (ZipEntry e; (e = z.getNextEntry()) != null; )
			{
				Matcher match = ENTRY.matcher(e.getName());
				if (e.isDirectory() || !match.matches())
				{
					continue;
				}
				if (id == null)
				{
					id = match.group(1);
				}
				else if (!id.equals(match.group(1)))
				{
					throw new IOException("the zip holds more than one pack");
				}
				if (++files > MAX_FILES)
				{
					throw new IOException("too many files");
				}
				String rel = match.group(2);
				long limit = rel.equals("voicepack.json") ? MAX_MANIFEST_BYTES : PackLoader.MAX_CLIP_BYTES;
				Filepath out = staging.join(id, rel.split("/"));
				out.getParent().createDirectories();
				total += copy(z, out, limit, rel);
				if (total > MAX_PACK_BYTES)
				{
					throw new IOException("the pack is larger than " + (MAX_PACK_BYTES >> 20) + " MB");
				}
			}
		}
		if (id == null)
		{
			throw new IOException("no voice pack in this zip (expected <pack>/voicepack.json)");
		}
		return id;
	}

	private static long copy(InputStream in, Filepath out, long limit, String name) throws IOException
	{
		byte[] buf = new byte[64 * 1024];
		long n = 0;
		try (OutputStream os = out.openOutputStream())
		{
			for (int r; (r = in.read(buf)) > 0; )
			{
				n += r;
				if (n > limit)
				{
					throw new IOException(name + " is too large");
				}
				os.write(buf, 0, r);
			}
		}
		return n;
	}

	private PackManifest readManifest(Filepath dir) throws IOException
	{
		Filepath f = dir.joinSegment("voicepack.json");
		if (!f.isFile())
		{
			throw new IOException("the zip has no voicepack.json");
		}
		try (Reader r = f.openBufferedReader())
		{
			PackManifest m = gson.fromJson(r, PackManifest.class);
			if (m == null || m.format != PackManifest.FORMAT || m.id == null)
			{
				throw new IOException("not a voice pack this plugin can read");
			}
			return m;
		}
		catch (JsonParseException e)
		{
			throw new IOException("voicepack.json is unreadable: " + e.getMessage());
		}
	}
}

package com.voicepacks.pack;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.voicepacks.trigger.EventType;
import com.voicepacks.trigger.TriggerEngine;
import java.io.IOException;
import java.io.Reader;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.util.Filepath;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Loads every pack folder under plugin-data/voice-packs/packs/. Uses {@link Filepath} only (the Plugin Hub forbids
 * java.io file APIs), so a pack can't reach outside its own folder.
 */
@Singleton
public class PackLoader
{
	private static final Logger log = LoggerFactory.getLogger(PackLoader.class);
	private static final Pattern LINE_FILE = Pattern.compile("audio/[A-Za-z0-9._-]+\\.wav");
	static final long MAX_CLIP_BYTES = 30 * 48_000 + 1024;   // ~30 s of 24 kHz mono 16-bit (~16 s at 44.1 kHz)

	/** The result of a load: built off the client thread, then swapped in whole. */
	public static final class Loaded
	{
		public final TriggerEngine engine = new TriggerEngine(new Random());
		public final List<String> packs = new ArrayList<>();
		public final List<PackManifest> manifests = new ArrayList<>();
		private final Map<String, Filepath> audio = new HashMap<>();

		public Filepath audioFor(String packId, String file)
		{
			return audio.get(packId + "/" + file);
		}
	}

	@Inject
	private Gson gson;

	/**
	 * @param enabled pack ids to load; empty loads all
	 */
	public Loaded load(Filepath packsDir, Set<String> enabled) throws IOException
	{
		Loaded result = new Loaded();
		if (!packsDir.exists())
		{
			packsDir.createDirectories();
		}
		List<Filepath> dirs;
		try (Stream<Filepath> s = packsDir.walk(1))
		{
			dirs = s.filter(p -> !p.equals(packsDir) && p.isDirectory() && !p.getFileName().startsWith("."))
				.sorted().collect(Collectors.toList());     // hidden folders are imports in progress
		}
		for (Filepath dir : dirs)
		{
			if (!enabled.isEmpty() && !enabled.contains(dir.getFileName()))
			{
				continue;
			}
			try
			{
				PackManifest m = loadPack(dir, result);
				result.packs.add(m.name + " " + m.version);
				result.manifests.add(m);
			}
			catch (IOException | JsonParseException | IllegalArgumentException e)
			{
				log.warn("Skipping voice pack {}: {}", dir.getFileName(), e.getMessage());
			}
		}
		log.info("Loaded {} voice pack(s), {} triggers: {}", result.packs.size(), result.engine.size(), result.packs);
		return result;
	}

	private PackManifest loadPack(Filepath dir, Loaded result) throws IOException
	{
		PackManifest m;
		try (Reader r = dir.joinSegment("voicepack.json").openBufferedReader())
		{
			m = gson.fromJson(r, PackManifest.class);
		}
		if (m == null || m.format != PackManifest.FORMAT)
		{
			throw new IllegalArgumentException("unsupported format " + (m == null ? "?" : m.format));
		}
		if (!dir.getFileName().equals(m.id))
		{
			throw new IllegalArgumentException("folder name differs from id " + m.id);
		}
		for (PackManifest.Trigger t : m.triggers)
		{
			EventType type = EventType.fromKey(t.event);
			if (type == null)
			{
				log.debug("{}: skipping trigger {} (unknown event {})", m.id, t.id, t.event);
				continue;
			}
			if (!t.when.keySet().stream().allMatch(type::allows))
			{
				log.warn("{}: skipping trigger {}: unknown fields in {}", m.id, t.id, t.when.keySet());
				continue;
			}
			List<PackManifest.Line> playable = new ArrayList<>();
			for (PackManifest.Line line : t.lines)
			{
				Filepath f = resolveLine(dir, line);
				if (f != null)
				{
					result.audio.put(m.id + "/" + line.file, f);
					playable.add(line);
				}
			}
			if (!playable.isEmpty())
			{
				t.lines = playable;
				result.engine.add(m.id, t, type, m.defaults);
			}
		}
		return m;
	}

	private Filepath resolveLine(Filepath dir, PackManifest.Line line) throws IOException
	{
		if (line.file == null || !LINE_FILE.matcher(line.file).matches())
		{
			log.warn("Bad line path {}", line.file);
			return null;
		}
		Filepath f = dir.join(line.file);          // throws if it would escape the pack folder
		if (!f.isFile() || f.size() > MAX_CLIP_BYTES)
		{
			log.warn("Missing or oversized clip {}", f);
			return null;
		}
		return f;
	}
}

package com.voicepacks.pack;

import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * voicepack.json, format 1. Field names match schema/voicepack.schema.json; Gson fills them and ignores unknown
 * keys, so packs can carry fields newer than this plugin as long as {@link #format} doesn't change.
 */
public class PackManifest
{
	public static final int FORMAT = 1;

	public int format;
	public String id;
	public String name;
	public String version;
	public String author;
	public String description;
	public Voice voice;
	public Tuning defaults;
	public List<Trigger> triggers = Collections.emptyList();

	public static class Voice
	{
		public String engine;
		public boolean cloned;
		public String likeness;      // original | licensed | real-person
		public String distribution;  // private | shareable
	}

	/** Per-trigger tuning; null means "inherit from defaults". */
	public static class Tuning
	{
		public Integer priority;
		public Double cooldownSeconds;
		public Double chance;
		public String pick;          // shuffle | random | sequence
		public Double volume;
	}

	public static class Trigger extends Tuning
	{
		public String id;
		public String event;
		/** field -> scalar | list | {min,max}; values arrive from Gson as String, Double, Boolean, List or Map. */
		public Map<String, Object> when = Collections.emptyMap();
		public List<Line> lines = Collections.emptyList();
	}

	public static class Line
	{
		public String file;
		public String text;
		public double weight = 1;
		public double gainDb;
		/** Plays at most this many times per account, ever; 0 = unlimited. */
		public int maxPlays;
	}
}

package com.voicepacks.source;

import com.voicepacks.trigger.EventSink;
import com.voicepacks.trigger.EventType;
import com.voicepacks.trigger.GameEvent;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Achievement events announced by game messages. The patterns are fixed in code; packs never supply them.
 * Kill-count and pet wording follows the Dink plugin's notifiers.
 */
public class ChatSource
{
	private static final Pattern QUEST = Pattern.compile("Congratulations, you've completed a quest: (.+?)\\.?$");
	private static final Pattern DIARY = Pattern.compile("completed all of the (\\w+) tasks in the (.+?) area");
	private static final Pattern COMBAT_TASK = Pattern.compile("Congratulations, you've completed an? (\\w+) combat task");
	private static final Pattern COLLECTION_LOG = Pattern.compile("New item added to your collection log: (.+)$");
	private static final Pattern CLUE = Pattern.compile("You have completed ([\\d,]+) (\\w+) Treasure Trails?\\.");
	private static final Pattern SLAYER = Pattern.compile("You have completed your task! You killed");
	private static final Pattern PET = Pattern.compile(
		"You have a funny feeling like you(?:'re being| would have been) followed|You feel something weird sneaking into your backpack");
	private static final Pattern UNTRADEABLE = Pattern.compile("Untradeable drop: (.+)$");
	private static final Pattern VALUABLE_DROP = Pattern.compile("Valuable drop: (.+?) \\(([\\d,]+) coins\\)");
	private static final Pattern MUSIC = Pattern.compile("You have unlocked a new music track: (.+?)\\.?$");
	private static final Pattern KC = Pattern.compile(
		"Your (.+?)\\s(?:kill|chest|completion|harvest|success|opened|lap)\\s?count is: ?([\\d,]+)\\b", Pattern.CASE_INSENSITIVE);
	private static final Pattern KC_PREFIXED = Pattern.compile("Your (?:completed|subdued) (.+?) count is: ([\\d,]+)\\b");
	/** Ticks to wait after a pet message for the item message that names the pet. */
	private static final int PET_NAME_TICKS = 3;

	@Inject
	private EventSink sink;

	private GameEvent pendingPet;
	private int pendingPetTicks;

	@Subscribe
	public void onChatMessage(ChatMessage chatMessage)
	{
		if (chatMessage.getType() != ChatMessageType.GAMEMESSAGE && chatMessage.getType() != ChatMessageType.SPAM)
		{
			return;
		}
		String msg = Text.removeTags(chatMessage.getMessage());
		if (pendingPet != null)
		{
			String name = petName(msg);
			if (name != null)
			{
				pendingPet.with("pet", name);
			}
		}
		GameEvent event = parse(msg);
		if (event == null)
		{
			return;
		}
		if (event.getType() == EventType.PET)
		{
			pendingPet = event;                    // held until the name arrives or a few ticks pass
			pendingPetTicks = PET_NAME_TICKS;
		}
		else
		{
			sink.accept(event);
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (pendingPet != null && (pendingPet.get("pet") != null || --pendingPetTicks <= 0))
		{
			sink.accept(pendingPet);
			pendingPet = null;
		}
	}

	static GameEvent parse(String msg)
	{
		Matcher m;
		if ((m = QUEST.matcher(msg)).find())
		{
			return new GameEvent(EventType.QUEST_COMPLETE).with("quest", m.group(1));
		}
		if ((m = DIARY.matcher(msg)).find())
		{
			return new GameEvent(EventType.DIARY_COMPLETE).with("tier", lower(m.group(1))).with("area", m.group(2));
		}
		if ((m = COMBAT_TASK.matcher(msg)).find())
		{
			return new GameEvent(EventType.COMBAT_TASK).with("tier", lower(m.group(1)));
		}
		if ((m = COLLECTION_LOG.matcher(msg)).find())
		{
			return new GameEvent(EventType.COLLECTION_LOG).with("item", m.group(1));
		}
		if ((m = CLUE.matcher(msg)).find())
		{
			return new GameEvent(EventType.CLUE_COMPLETE).with("count", number(m.group(1))).with("tier", lower(m.group(2)));
		}
		if (SLAYER.matcher(msg).find())
		{
			return new GameEvent(EventType.SLAYER_TASK);
		}
		if ((m = PET.matcher(msg)).find())
		{
			return new GameEvent(EventType.PET).with("duplicate", m.group().contains("would have been"));
		}
		if ((m = VALUABLE_DROP.matcher(msg)).find())
		{
			return new GameEvent(EventType.VALUABLE_DROP).with("item", m.group(1)).with("value", number(m.group(2)));
		}
		if ((m = MUSIC.matcher(msg)).find())
		{
			return new GameEvent(EventType.MUSIC_UNLOCK).with("track", m.group(1));
		}
		if ((m = KC_PREFIXED.matcher(msg)).find() || (m = KC.matcher(msg)).find())
		{
			return new GameEvent(EventType.BOSS_KC).with("boss", m.group(1).trim()).with("kc", number(m.group(2)));
		}
		return null;
	}

	static String petName(String msg)
	{
		Matcher m = UNTRADEABLE.matcher(msg);
		if (m.find())
		{
			return m.group(1).trim();
		}
		m = COLLECTION_LOG.matcher(msg);
		return m.find() ? m.group(1).trim() : null;
	}

	private static long number(String s)
	{
		return Long.parseLong(s.replace(",", ""));
	}

	private static String lower(String s)
	{
		return s.toLowerCase(Locale.ROOT);
	}
}

package com.voicepacks.source;

import com.voicepacks.trigger.EventSink;
import com.voicepacks.trigger.EventType;
import com.voicepacks.trigger.GameEvent;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.NPC;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;

/**
 * LOOT events: NPC drops (core LootManager) and non-NPC loot such as raid chests, Barrows and clue caskets (the
 * Loot Tracker's LootReceived, EVENT type only, since NPC kills arrive through NpcLootReceived already). Fields:
 * source, item (every item name, so a pack can match any one), top (the most valuable item) and value (total GE
 * value). The journey store adds record / sourceRecord.
 */
public class LootSource
{
	@Inject
	private ItemManager itemManager;

	@Inject
	private EventSink sink;

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		NPC npc = event.getNpc();
		emit(npc == null ? null : npc.getName(), event.getItems());
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		if (event.getType() == LootRecordType.EVENT)
		{
			emit(event.getName(), event.getItems());
		}
	}

	private void emit(String source, Collection<ItemStack> items)
	{
		if (source == null || items.isEmpty())
		{
			return;
		}
		List<String> names = new ArrayList<>();
		long total = 0;
		long topValue = -1;
		String top = null;
		for (ItemStack stack : items)
		{
			String name = itemManager.getItemComposition(stack.getId()).getName();
			long value = (long) itemManager.getItemPrice(stack.getId()) * stack.getQuantity();
			names.add(name);
			total += value;
			if (value > topValue)
			{
				topValue = value;
				top = name;
			}
		}
		sink.accept(new GameEvent(EventType.LOOT).with("source", source).with("item", names).with("top", top)
			.with("value", total));
	}
}

package com.voicepacks.source;

import com.voicepacks.trigger.EventSink;
import com.voicepacks.trigger.EventType;
import com.voicepacks.trigger.GameEvent;
import java.util.EnumMap;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.eventbus.Subscribe;

/**
 * Level-ups (from an XP baseline, the approach c-engineer-completed uses, so logins and world hops don't fire),
 * deaths and logins.
 */
public class ProgressSource
{
	@Inject
	private Client client;

	@Inject
	private EventSink sink;

	private final Map<Skill, Integer> lastXp = new EnumMap<>(Skill.class);
	private GameState lastState = GameState.UNKNOWN;
	/** LOGIN fires a few ticks after logging in, once the account's profile (and journey memory) has loaded. */
	private int loginTicks;

	public void reset()
	{
		lastXp.clear();
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Skill skill = event.getSkill();
		int xpAfter = event.getXp();
		Integer xpBefore = lastXp.put(skill, xpAfter);
		if (xpBefore == null || xpAfter <= xpBefore)
		{
			return;                                // first sighting since login, or no gain
		}
		int before = Experience.getLevelForXp(xpBefore);
		int after = Experience.getLevelForXp(xpAfter);
		if (after <= before)
		{
			return;
		}
		boolean virtual = after > Experience.MAX_REAL_LEVEL;
		String milestone = after == Experience.MAX_REAL_LEVEL ? "99" : after == Experience.MAX_VIRT_LEVEL ? "virtual_max" : null;
		GameEvent levelUp = new GameEvent(EventType.LEVEL_UP)
			.with("skill", skill.getName().toLowerCase(Locale.ROOT))
			.with("level", after)
			.with("virtual", virtual);
		if (milestone != null)
		{
			levelUp.with("milestone", milestone);
		}
		sink.accept(levelUp);
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (event.getActor() == client.getLocalPlayer())
		{
			sink.accept(new GameEvent(EventType.DEATH));
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN && lastState == GameState.LOGGING_IN)
		{
			loginTicks = 3;                         // world hops go HOPPING -> LOGGING_IN too; refine later
		}
		if (state == GameState.LOGIN_SCREEN)
		{
			lastXp.clear();
		}
		lastState = state;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (loginTicks > 0 && --loginTicks == 0)
		{
			sink.accept(new GameEvent(EventType.LOGIN));
		}
	}
}

package com.voicepacks.trigger;

import java.util.ArrayList;
import java.util.List;
import javax.inject.Singleton;

/**
 * Events collected during the current game tick. Sources add on the client thread; the plugin drains once per tick
 * and plays at most one line, so a quest that grants three levels at once says one thing, not four.
 */
@Singleton
public class EventSink
{
	private final List<GameEvent> pending = new ArrayList<>();

	public void accept(GameEvent event)
	{
		pending.add(event);
	}

	public List<GameEvent> drain()
	{
		List<GameEvent> out = new ArrayList<>(pending);
		pending.clear();
		return out;
	}
}

package com.voicepacks.trigger;

import java.util.Locale;
import java.util.Set;

/**
 * The fixed trigger catalogue (mirrors schema/events.json). Packs can only fill these slots. Every event is detected
 * by fixed code in the plugin; none takes IDs, game-message text or NPC names from a pack (Plugin Hub rule).
 */
public enum EventType
{
	LEVEL_UP("milestone", "skill", "level", "virtual", "milestone", "multi"),
	XP_MILESTONE("skill", "skill", "xp"),
	QUEST_COMPLETE(null, "quest"),
	DIARY_COMPLETE("tier", "area", "tier"),
	COMBAT_TASK("tier", "tier"),
	COLLECTION_LOG(null, "item", "boss", "dryKc"),
	CLUE_COMPLETE("tier", "tier", "count"),
	SLAYER_TASK(null),
	BOSS_KC("boss", "boss", "kc", "dryKc"),
	PET(null, "pet", "duplicate", "boss", "dryKc"),
	LOOT("source", "source", "item", "top", "value", "record", "sourceRecord"),
	VALUABLE_DROP(null, "item", "value"),
	DEATH(null),
	LOGIN(null, "daysAway"),
	MUSIC_UNLOCK(null, "track");

	/** Filled on every event by the plugin (who the player is, when, where). */
	public static final Set<String> CONTEXT_FIELDS = Set.of("account", "totalLevel", "combatLevel", "questPoints",
		"world", "timeOfDay", "weekday", "holiday", "sessionMinutes", "inWilderness", "afterAction");

	/** Filled on every event from the account's journey memory. */
	public static final Set<String> JOURNEY_FIELDS = Set.of("first", "count", "firstAll", "countAll", "sinceLastDays");

	private final String keyField;
	private final Set<String> fields;

	EventType(String keyField, String... fields)
	{
		this.keyField = keyField;
		this.fields = Set.of(fields);
	}

	/** The field "first"/"count" are counted per (e.g. per boss), or null to count the event type as a whole. */
	public String getKeyField()
	{
		return keyField;
	}

	public Set<String> getFields()
	{
		return fields;
	}

	/** Whether a pack's {@code when} may name this field for this event. */
	public boolean allows(String field)
	{
		return fields.contains(field) || CONTEXT_FIELDS.contains(field) || JOURNEY_FIELDS.contains(field);
	}

	/** "level_up" -> LEVEL_UP, or null if the pack names an event this plugin doesn't know. */
	public static EventType fromKey(String key)
	{
		try
		{
			return key == null ? null : valueOf(key.toUpperCase(Locale.ROOT));
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}
}

package com.voicepacks.trigger;

import java.util.HashMap;
import java.util.Map;

/** Something that happened in game, reduced to an event type and the fields packs may filter on. */
public final class GameEvent
{
	private final EventType type;
	private final Map<String, Object> fields = new HashMap<>();

	public GameEvent(EventType type)
	{
		this.type = type;
	}

	public GameEvent with(String field, Object value)
	{
		fields.put(field, value);
		return this;
	}

	public EventType getType()
	{
		return type;
	}

	public Object get(String field)
	{
		return fields.get(field);
	}

	@Override
	public String toString()
	{
		return type + fields.toString();
	}
}

package com.voicepacks.trigger;

import com.voicepacks.pack.PackManifest.Line;
import com.voicepacks.pack.PackManifest.Trigger;
import com.voicepacks.pack.PackManifest.Tuning;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.Deque;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Random;
import java.util.stream.Collectors;

/**
 * Picks the line to say for a game event. Pure Java (no RuneLite types) so it can be unit tested.
 *
 * <p>Candidates for an event are ranked by priority, then specificity (number of {@code when} keys), then pack and
 * declaration order. The first matching candidate that is off cooldown wins, so a pack can hold hundreds of
 * specific lines (per quest, per skill, per level) and a few generic ones that cover everything else. Achievement
 * events are rare, so a linear scan per event is plenty fast even for thousands of triggers.
 */
public class TriggerEngine
{
	/** A loaded trigger with its pack's defaults applied. */
	public static final class Candidate
	{
		final String packId;
		final Trigger trigger;
		final int priority;
		final double cooldownMs;
		final double chance;
		final String pick;
		final double volume;
		final int order;

		Candidate(String packId, Trigger trigger, Tuning defaults, int order)
		{
			this.packId = packId;
			this.trigger = trigger;
			this.priority = first(trigger.priority, defaults == null ? null : defaults.priority, 50);
			this.cooldownMs = 1000 * first(trigger.cooldownSeconds, defaults == null ? null : defaults.cooldownSeconds, 0.0);
			this.chance = first(trigger.chance, defaults == null ? null : defaults.chance, 1.0);
			this.pick = first(trigger.pick, defaults == null ? null : defaults.pick, "shuffle");
			this.volume = first(trigger.volume, defaults == null ? null : defaults.volume, 1.0);
			this.order = order;
		}

		String key()
		{
			return packId + "/" + trigger.id;
		}

		int specificity()
		{
			return trigger.when.size();
		}
	}

	/** How often each line has played on this account (journey memory); drives {@code maxPlays}. */
	public interface PlayCounts
	{
		int plays(String lineKey);

		void played(String lineKey);
	}

	/** What to play. */
	public static final class Selection
	{
		public final String packId;
		public final String triggerId;
		public final Line line;
		public final int priority;
		public final double volume;

		Selection(Candidate c, Line line)
		{
			this.packId = c.packId;
			this.triggerId = c.trigger.id;
			this.line = line;
			this.priority = c.priority;
			this.volume = c.volume;
		}
	}

	private static final Comparator<Candidate> RANK = Comparator
		.comparingInt((Candidate c) -> -c.priority)
		.thenComparingInt(c -> -c.specificity())
		.thenComparingInt(c -> c.order);

	private final Map<EventType, List<Candidate>> byEvent = new EnumMap<>(EventType.class);
	private final Map<String, Long> lastFired = new HashMap<>();
	private final Map<String, Deque<Line>> bags = new HashMap<>();
	private final Map<String, Integer> sequence = new HashMap<>();
	private final Random random;
	private PlayCounts playCounts = new PlayCounts()
	{
		private final Map<String, Integer> counts = new HashMap<>();

		@Override
		public int plays(String lineKey)
		{
			return counts.getOrDefault(lineKey, 0);
		}

		@Override
		public void played(String lineKey)
		{
			counts.merge(lineKey, 1, Integer::sum);
		}
	};
	private int order;

	public TriggerEngine(Random random)
	{
		this.random = random;
	}

	public void setPlayCounts(PlayCounts playCounts)
	{
		this.playCounts = playCounts;
	}

	public static String lineKey(String packId, Line line)
	{
		return packId + "/" + line.file;
	}

	public void clear()
	{
		byEvent.clear();
		lastFired.clear();
		bags.clear();
		sequence.clear();
		order = 0;
	}

	public void add(String packId, Trigger trigger, EventType type, Tuning defaults)
	{
		List<Candidate> list = byEvent.computeIfAbsent(type, t -> new ArrayList<>());
		list.add(new Candidate(packId, trigger, defaults, order++));
		list.sort(RANK);
	}

	public int size()
	{
		return byEvent.values().stream().mapToInt(List::size).sum();
	}

	/** The line to play for {@code event}, or null to stay quiet. */
	public Selection select(GameEvent event, long nowMs)
	{
		for (Candidate c : byEvent.getOrDefault(event.getType(), Collections.emptyList()))
		{
			if (!matches(c.trigger.when, event))
			{
				continue;
			}
			List<Line> lines = available(c);
			if (lines.isEmpty())
			{
				continue;                          // every once-only line used up: fall back
			}
			Long last = lastFired.get(c.key());
			if (last != null && nowMs - last < c.cooldownMs)
			{
				continue;                          // fall back to a less specific line
			}
			if (c.chance < 1 && random.nextDouble() >= c.chance)
			{
				return null;                       // the best match chose silence; don't play a generic line instead
			}
			lastFired.put(c.key(), nowMs);
			Line line = pickLine(c, lines);
			playCounts.played(lineKey(c.packId, line));
			return new Selection(c, line);
		}
		return null;
	}

	private List<Line> available(Candidate c)
	{
		return c.trigger.lines.stream()
			.filter(l -> l.maxPlays <= 0 || playCounts.plays(lineKey(c.packId, l)) < l.maxPlays)
			.collect(Collectors.toList());
	}

	private Line pickLine(Candidate c, List<Line> lines)
	{
		switch (c.pick)
		{
			case "sequence":
			{
				int i = sequence.merge(c.key(), 1, Integer::sum) - 1;
				return lines.get(i % lines.size());
			}
			case "random":
			{
				double total = lines.stream().mapToDouble(l -> l.weight).sum();
				double r = random.nextDouble() * total;
				for (Line l : lines)
				{
					r -= l.weight;
					if (r < 0)
					{
						return l;
					}
				}
				return lines.get(lines.size() - 1);
			}
			default:                               // shuffle: every line once before any repeats
			{
				Deque<Line> bag = bags.computeIfAbsent(c.key(), k -> new ArrayDeque<>());
				bag.retainAll(lines);              // drop lines that have since hit maxPlays
				if (bag.isEmpty())
				{
					List<Line> shuffled = new ArrayList<>(lines);
					Collections.shuffle(shuffled, random);
					bag.addAll(shuffled);
				}
				return bag.poll();
			}
		}
	}

	static boolean matches(Map<String, Object> when, GameEvent event)
	{
		for (Map.Entry<String, Object> e : when.entrySet())
		{
			if (!matchesOne(e.getValue(), event.get(e.getKey())))
			{
				return false;
			}
		}
		return true;
	}

	private static boolean matchesOne(Object cond, Object actual)
	{
		if (cond instanceof String && "any".equalsIgnoreCase((String) cond))
		{
			return actual != null;
		}
		if (actual == null)
		{
			return false;
		}
		if (actual instanceof Collection)          // e.g. every item in a loot drop: any one may match
		{
			return ((Collection<?>) actual).stream().anyMatch(a -> matchesOne(cond, a));
		}
		if (cond instanceof Collection)
		{
			return ((Collection<?>) cond).stream().anyMatch(c -> matchesOne(c, actual));
		}
		if (cond instanceof Map)
		{
			if (!(actual instanceof Number))
			{
				return false;
			}
			double v = ((Number) actual).doubleValue();
			Object min = ((Map<?, ?>) cond).get("min");
			Object max = ((Map<?, ?>) cond).get("max");
			return (!(min instanceof Number) || v >= ((Number) min).doubleValue())
				&& (!(max instanceof Number) || v <= ((Number) max).doubleValue());
		}
		if (cond instanceof Number && actual instanceof Number)
		{
			return ((Number) cond).doubleValue() == ((Number) actual).doubleValue();
		}
		if (cond instanceof Boolean)
		{
			return cond.equals(actual);
		}
		return String.valueOf(cond).toLowerCase(Locale.ROOT).equals(String.valueOf(actual).toLowerCase(Locale.ROOT));
	}

	private static <T> T first(T a, T b, T fallback)
	{
		return a != null ? a : b != null ? b : fallback;
	}
}

package com.voicepacks;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.voicepacks.pack.PackManifest;
import com.voicepacks.trigger.TriggerEngine;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Random;
import org.junit.Assume;

import com.voicepacks.trigger.EventType;
import com.voicepacks.trigger.GameEvent;
import org.junit.Test;

public class DemoCommandTest
{
	@Test
	public void parsesTypedFields()
	{
		String[] args = {"boss_kc", "boss=Corporeal_Beast", "kc=1", "first=true", "timeOfDay=late"};
		assertEquals(EventType.BOSS_KC, DemoCommand.type(args));
		GameEvent e = DemoCommand.apply(new GameEvent(EventType.BOSS_KC).with("timeOfDay", "morning"), args);
		assertEquals("Corporeal Beast", e.get("boss"));
		assertEquals(1L, e.get("kc"));
		assertEquals(true, e.get("first"));
		assertEquals("late", e.get("timeOfDay"));
		assertNull(DemoCommand.type(new String[]{"nonsense"}));
		assertNull(DemoCommand.type(new String[0]));
	}

	@Test
	public void everyShowcaseStepIsAValidEvent()
	{
		assertEquals(DemoCommand.SHOWCASE[0], String.join(" ", DemoCommand.showcase(1)));
		assertEquals(DemoCommand.SHOWCASE[0], String.join(" ", DemoCommand.showcase(DemoCommand.SHOWCASE.length + 1)));
		for (int n = 1; n <= DemoCommand.SHOWCASE.length; n++)
		{
			String[] args = DemoCommand.showcase(n);
			EventType type = DemoCommand.type(args);
			assertNotNull(args[0], type);
			for (int i = 1; i < args.length; i++)
			{
				String field = args[i].substring(0, args[i].indexOf('='));
				assertTrue(args[0] + " " + field, type.allows(field));
			}
		}
	}

	/** Steps 16-21 must reach the lines vgen drafted, not a generic fallback. */
	private static final String[] SPECIFIC = {"quest-song-of-the-elves", "boss-tztok-jad-first",
		"boss-vorkath-milestone", "pet-vorki", "clog-twisted-bow", "clog-scythe-of-vitur"};

	/** With an example pack built by the packer (../out/mlx/<pack>), every showcase step must pick a line. */
	@Test
	public void everyShowcaseStepPlaysALineFromTheExamplePack() throws Exception
	{
		PackManifest m = examplePack();
		Assume.assumeNotNull(m);
		TriggerEngine engine = new TriggerEngine(new Random(1));
		for (PackManifest.Trigger t : m.triggers)
		{
			engine.add(m.id, t, EventType.fromKey(t.event), m.defaults);
		}
		for (int n = 1; n <= DemoCommand.SHOWCASE.length; n++)
		{
			String[] args = DemoCommand.showcase(n);
			GameEvent e = DemoCommand.apply(new GameEvent(DemoCommand.type(args)).with("timeOfDay", "afternoon"), args);
			TriggerEngine.Selection picked = engine.select(e, n * 60_000L);
			assertNotNull("no line for demo " + n + ": " + DemoCommand.SHOWCASE[n - 1], picked);
			if (n > 15)
			{
				assertEquals(SPECIFIC[n - 16], picked.triggerId);
			}
		}
	}

	/** The first locally built pack that has every specific showcase trigger, or null. */
	private static PackManifest examplePack() throws Exception
	{
		Path built = Path.of("../out/mlx");
		if (!Files.isDirectory(built))
		{
			return null;
		}
		try (var dirs = Files.list(built))
		{
			for (Path dir : (Iterable<Path>) dirs.sorted()::iterator)
			{
				Path manifest = dir.resolve("voicepack.json");
				if (!Files.isRegularFile(manifest))
				{
					continue;
				}
				PackManifest m = new Gson().fromJson(Files.readString(manifest), PackManifest.class);
				var ids = m.triggers.stream().map(t -> t.id).collect(java.util.stream.Collectors.toSet());
				if (ids.containsAll(java.util.List.of(SPECIFIC)))
				{
					return m;
				}
			}
		}
		return null;
	}
}

